<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { useRouter,onBeforeRouteLeave } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import { api, apiResult } from '../../lib/api'
import { canGateway } from '../../lib/auth'
import { pretty } from '../../lib/format'
import { canonicalUuid, enc, errorText, hasCapability, payload, taskIntent, type Row } from './utils'
const props=defineProps<{gateway:Row}>(), router=useRouter()
const loading=ref(false),busy=ref(false),error=ref(''),info=ref(''),config=ref<Row>({}),effective=ref<Row>({}),etag=ref(''),section=ref('network'),changed=reactive<Record<string,boolean>>({}),task=ref<Row>(),intent=taskIntent()
const form=reactive<Row>({uplinkOrder:['ETHERNET'],ethernetEnabled:false,ethernetIPv4:{mode:'DHCP',address:'',prefixLength:24,gateway:'',dns:''},wifiEnabled:false,ssid:'',security:'WPA2_PSK',credentialRef:'',wifiIPv4:{mode:'DHCP',address:'',prefixLength:24,gateway:'',dns:''},enabled:false,active:false,intervalMs:100,windowMs:100,minRssi:-80,clearRssi:false,serviceUuids:'',manufacturerIds:'',beaconRules:[],mode:'NONCONNECTABLE',advInterval:1000,advData:'',scanResponse:'',encoding:'HEX',batchMaxRecords:32,flushIntervalMs:1000})
const sections=computed(()=>hasCapability(props.gateway,'GW32_CONTROL_PROFILE_1')?[{id:'network',label:'网络'},{id:'nrf54-scan',label:'nRF 扫描与过滤'},{id:'nrf54-advertising',label:'nRF 广播'},{id:'esp32-scan',label:'ESP 扫描与过滤'},{id:'esp32-advertising',label:'ESP 广播'},{id:'upload',label:'上传参数'}]:[{id:'legacy-scan',label:'兼容扫描与过滤'},{id:'upload',label:'上传参数'}])
const radio=computed(()=>section.value.startsWith('esp32')?'esp32':'nrf54')
const isScan=computed(()=>section.value.endsWith('-scan')),isAdv=computed(()=>section.value.endsWith('-advertising'))
const supported=computed(()=>section.value==='upload'||section.value==='legacy-scan'||hasCapability(props.gateway,'GW32_CONTROL_PROFILE_1')&&(section.value==='network'||hasCapability(props.gateway,radio.value.toUpperCase()+(isScan.value?'_BLE_SCAN':'_BLE_ADV'))))
const allowed=computed(()=>canGateway('gateway:configure',props.gateway)&&canGateway('task:create',props.gateway)&&hasCapability(props.gateway,'CONFIGURE')&&props.gateway.state==='ACTIVE'&&supported.value)
const snapshot=computed(()=>effective.value.configuration||{})
function clear(){for(const k of Object.keys(changed))delete changed[k];task.value=undefined;error.value='';info.value=''}
function loadKnown(){clear();const source=section.value==='network'?snapshot.value.network:section.value==='upload'?snapshot.value.upload:section.value==='legacy-scan'?snapshot.value:snapshot.value.radios?.[radio.value]||{};if(!source)return
 if(section.value==='network'){if(source.uplinkOrder)form.uplinkOrder=[...source.uplinkOrder];if(source.ethernet?.enabled!==undefined)form.ethernetEnabled=source.ethernet.enabled;if(source.wifiSta?.enabled!==undefined)form.wifiEnabled=source.wifiSta.enabled;for(const k of ['ssid','security','credentialRef'])if(source.wifiSta?.[k]!==undefined)form[k]=source.wifiSta[k];for(const [name,v] of [['ethernetIPv4',source.ethernet?.ipv4],['wifiIPv4',source.wifiSta?.ipv4]] as const)if(v)form[name]={...v,dns:(v.dns||[]).join(', ')} }
 else if(section.value==='upload'){for(const k of ['batchMaxRecords','flushIntervalMs'])if(source[k]!==undefined)form[k]=source[k]}
 else if(isScan.value){for(const k of ['enabled','active','intervalMs','windowMs'])if(source.scan?.[k]!==undefined)form[k]=source.scan[k];if(source.filters?.minRssi!==undefined){form.clearRssi=source.filters.minRssi===null;form.minRssi=source.filters.minRssi??-80}form.serviceUuids=(source.filters?.serviceUuids||[]).join(', ');form.manufacturerIds=(source.filters?.manufacturerIds||[]).join(', ');form.beaconRules=(source.beaconRules||[]).map((r:Row)=>({...r,encoding:'BASE64',value:r.valueBase64,mask:r.maskBase64}))}
 else{const a=source.advertising||{};for(const k of ['enabled','mode'])if(a[k]!==undefined)form[k]=a[k];if(a.intervalMs!==undefined)form.advInterval=a.intervalMs;form.encoding='BASE64';form.advData=a.advDataBase64||'';form.scanResponse=a.scanResponseBase64||''}
}
async function load(preserve=true){loading.value=true;error.value='';try{const result=await apiResult<Row>(`/api/v1/gateways/${enc(props.gateway.gatewayId)}/configuration`);config.value=result.data;etag.value=result.etag;try{effective.value=await api(`/api/v1/gateways/${enc(props.gateway.gatewayId)}/configuration/effective`)}catch(e:any){if(e.status!==404)throw e;effective.value={configuration:{},complete:false}}if(!preserve||!Object.values(changed).some(Boolean))loadKnown();else info.value='版本和已知配置已刷新，草稿已保留。请比较后再提交。'}catch(e){error.value=errorText(e)}finally{loading.value=false}}
watch(()=>props.gateway.gatewayId,()=>{section.value=hasCapability(props.gateway,'GW32_CONTROL_PROFILE_1')?'network':'legacy-scan';void load(false)},{immediate:true});watch(section,loadKnown)
async function discardAllowed(){if(task.value||!Object.values(changed).some(Boolean))return true;try{await ElMessageBox.confirm('当前配置草稿尚未提交。离开会清除这些修改。','放弃草稿？',{confirmButtonText:'放弃并离开',cancelButtonText:'继续编辑',type:'warning'});return true}catch{return false}}
async function selectSection(next:string){if(next===section.value)return;if(await discardAllowed())section.value=next}
onBeforeRouteLeave(discardAllowed)
function ipv4(v:Row){if(v.mode==='DHCP')return{mode:'DHCP'};const dns=String(v.dns).split(/[,\s]+/).filter(Boolean);const parse=(s:string)=>{const p=s.split('.');if(p.length!==4||p.some(x=>!/^\d{1,3}$/.test(x)||Number(x)>255))throw new Error('请输入有效的 IPv4 地址');return p.reduce((a,b)=>(a*256+Number(b))>>>0,0)};if(!v.address||!v.gateway||dns.length<1||dns.length>2)throw new Error('静态 IPv4 需要地址、网关和 1–2 个 DNS');const a=parse(v.address),g=parse(v.gateway);dns.forEach(parse);const mask=(0xffffffff<<(32-v.prefixLength))>>>0;if((a&mask)!==(g&mask))throw new Error('静态地址与网关必须位于同一子网');return{mode:'STATIC',address:v.address,prefixLength:v.prefixLength,gateway:v.gateway,dns}}
function build(){const c=changed,f=form;let result:Row={}
 if(section.value==='network'){const network:Row={};if(c.uplinkOrder){if(!f.uplinkOrder.length)throw new Error('至少选择一个上行接口');network.uplinkOrder=[...f.uplinkOrder]};const ethernet:Row={},wifi:Row={};if(c.ethernetEnabled)ethernet.enabled=f.ethernetEnabled;if(c.ethernetIPv4)ethernet.ipv4=ipv4(f.ethernetIPv4);if(c.wifiEnabled)wifi.enabled=f.wifiEnabled;for(const k of ['ssid','security','credentialRef'])if(c[k])wifi[k]=f[k];if(c.ssid&&(new TextEncoder().encode(f.ssid).length<1||new TextEncoder().encode(f.ssid).length>32))throw new Error('SSID 应为 1–32 个 UTF-8 字节');if(c.credentialRef&&!f.credentialRef.trim())throw new Error('请填写设备端 credentialRef');if(c.wifiIPv4)wifi.ipv4=ipv4(f.wifiIPv4);if(Object.keys(ethernet).length)network.ethernet=ethernet;if(Object.keys(wifi).length)network.wifiSta=wifi;if(Object.keys(network).length)result={network}}
 else if(section.value==='upload'){const upload:Row={};for(const k of ['batchMaxRecords','flushIntervalMs'])if(c[k])upload[k]=f[k];if(Object.keys(upload).length)result={upload}}
 else if(isScan.value){const scan:Row={},filters:Row={},r:Row={};for(const k of ['enabled','active','intervalMs','windowMs'])if(c[k])scan[k]=f[k];if(c.intervalMs&&c.windowMs&&f.windowMs>f.intervalMs)throw new Error('扫描窗口不能大于扫描间隔');if(c.minRssi)filters.minRssi=f.clearRssi&&section.value!=='legacy-scan'?null:f.minRssi;if(c.serviceUuids)filters.serviceUuids=f.serviceUuids.split(/[,\s]+/).filter(Boolean).map(canonicalUuid);if(c.manufacturerIds){filters.manufacturerIds=f.manufacturerIds.split(/[,\s]+/).filter(Boolean).map(Number);if(filters.manufacturerIds.some((n:number)=>!Number.isInteger(n)||n<0||n>65535))throw new Error('厂商 ID 必须为 0–65535 的整数')};if(Object.keys(scan).length)r.scan=scan;if(Object.keys(filters).length)r.filters=filters;if(c.beaconRules){if(!hasCapability(props.gateway,radio.value.toUpperCase()+'_BLE_BEACON_FILTER'))throw new Error('网关未声明 Beacon 过滤能力');r.beaconRules=f.beaconRules.map((v:Row)=>{const valueBase64=payload(v.value,v.encoding,24,1),maskBase64=payload(v.mask,v.encoding,24,1);if(atob(valueBase64).length!==atob(maskBase64).length)throw new Error('Beacon 值和掩码长度必须一致');if([...atob(maskBase64)].every(c=>c.charCodeAt(0)===0))throw new Error('Beacon 掩码不能全部为零');if(v.offset+atob(valueBase64).length>254)throw new Error('Beacon 偏移与长度超出 254 字节');if(!v.reportKinds.length)throw new Error('请选择 Beacon 报文类型');return{action:v.action,reportKinds:v.reportKinds,adType:v.adType,offset:v.offset,valueBase64,maskBase64}})};if(Object.keys(r).length)result=section.value==='legacy-scan'?r:{radios:{[radio.value]:r}}}
 else{const advertising:Row={};for(const k of ['enabled','mode'])if(c[k])advertising[k]=f[k];if(c.advInterval)advertising.intervalMs=f.advInterval;if(c.advData)advertising.advDataBase64=payload(f.advData,f.encoding,31,0,true);if(c.scanResponse)advertising.scanResponseBase64=payload(f.scanResponse,f.encoding,31,0,true);if(c.mode&&f.mode==='NONCONNECTABLE'&&c.scanResponse&&f.scanResponse.trim())throw new Error('不可扫描广播不能携带扫描响应');if(Object.keys(advertising).length)result={radios:{[radio.value]:{advertising}}}}
 if(!Object.keys(result).length)throw new Error('请勾选至少一个需要修改的字段');return result
}
const preview=computed(()=>{try{return{value:build(),error:''}}catch(e){return{value:null,error:errorText(e)}}})
async function submit(){if(!allowed.value)return;try{const configuration=build();await ElMessageBox.confirm('仅提交右侧所列变更。数组、IPv4 对象和 AD 载荷会整体替换；任务被受理后还需设备验证。','确认配置变更',{confirmButtonText:'创建配置任务',cancelButtonText:'返回编辑',type:'warning'});busy.value=true;error.value='';const request=intent({configuration,expectedReportedRevision:config.value.reportedRevision});task.value=await api(`/api/v1/gateways/${enc(props.gateway.gatewayId)}/configuration`,'PUT',request.body,{etag:etag.value,key:request.key});intent.clear();info.value='配置任务已创建，请查看设备执行和验证结果。'}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{busy.value=false}}
function addBeacon(){form.beaconRules.push({action:'ALLOW',reportKinds:['LEGACY_ADV'],adType:255,offset:0,encoding:'HEX',value:'',mask:''})}
</script>
<template><div v-loading="loading"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="info" :title="info" type="success" :closable="false"/>
 <div class="toolbar"><span>期望版本 {{config.desiredRevision??'—'}} · 已验证版本 {{config.reportedRevision??'—'}}</span><el-button @click="load()">刷新版本与已知配置</el-button></div>
 <el-alert title="勾选“本次修改”后该字段才会下发。已知配置来自已验证变更；未记录的字段保持未知，表单示例值不会自动写入设备。" type="info" :closable="false"/>
 <div class="config-grid"><el-menu :default-active="section" @select="selectSection"><el-menu-item v-for="s in sections" :key="s.id" :index="s.id">{{s.label}}</el-menu-item></el-menu>
 <el-form label-position="top" class="config-form">
 <el-alert v-if="!supported" title="网关未声明此配置组所需能力。" type="warning" :closable="false"/>
 <template v-if="section==='network'">
  <el-form-item label="上行优先顺序（选中顺序即优先级，整体替换）"><el-checkbox v-model="changed.uplinkOrder">本次修改</el-checkbox><el-select v-model="form.uplinkOrder" multiple :disabled="!changed.uplinkOrder"><el-option label="以太网" value="ETHERNET"/><el-option label="Wi-Fi STA" value="WIFI_STA"/></el-select></el-form-item>
  <el-form-item label="以太网"><el-checkbox v-model="changed.ethernetEnabled">本次修改启用状态</el-checkbox><el-switch v-model="form.ethernetEnabled" :disabled="!changed.ethernetEnabled"/></el-form-item>
  <el-form-item label="Wi-Fi STA"><el-checkbox v-model="changed.wifiEnabled">本次修改启用状态</el-checkbox><el-switch v-model="form.wifiEnabled" :disabled="!changed.wifiEnabled"/></el-form-item>
  <el-form-item v-for="field in [{key:'ssid',label:'Wi-Fi SSID'},{key:'credentialRef',label:'设备端凭据引用 credentialRef'}]" :key="field.key" :label="field.label"><el-checkbox v-model="changed[field.key]">本次修改</el-checkbox><el-input v-model="form[field.key]" :disabled="!changed[field.key]"/></el-form-item>
  <el-form-item label="Wi-Fi 安全模式"><el-checkbox v-model="changed.security">本次修改</el-checkbox><el-select v-model="form.security" :disabled="!changed.security"><el-option label="WPA2 PSK" value="WPA2_PSK"/><el-option label="WPA3 SAE" value="WPA3_SAE"/></el-select></el-form-item>
  <fieldset v-for="net in [{key:'ethernetIPv4',label:'以太网 IPv4'},{key:'wifiIPv4',label:'Wi-Fi IPv4'}]" :key="net.key"><legend>{{net.label}}</legend><el-checkbox v-model="changed[net.key]">整体替换此 IPv4 对象</el-checkbox><el-select v-model="form[net.key].mode" :disabled="!changed[net.key]"><el-option label="DHCP" value="DHCP"/><el-option label="静态地址" value="STATIC"/></el-select><template v-if="form[net.key].mode==='STATIC'"><el-input v-model="form[net.key].address" aria-label="IPv4 地址" placeholder="IPv4 地址" :disabled="!changed[net.key]"/><el-input-number v-model="form[net.key].prefixLength" aria-label="前缀长度" :min="1" :max="30" :disabled="!changed[net.key]"/><el-input v-model="form[net.key].gateway" aria-label="IPv4 网关" placeholder="同网段网关" :disabled="!changed[net.key]"/><el-input v-model="form[net.key].dns" aria-label="DNS" placeholder="1–2 个 DNS，逗号分隔" :disabled="!changed[net.key]"/></template></fieldset>
 </template>
 <template v-else-if="isScan">
  <el-form-item v-for="f in [{key:'enabled',label:'启用扫描'},{key:'active',label:'主动扫描'}]" :key="f.key" :label="f.label"><el-checkbox v-model="changed[f.key]">本次修改</el-checkbox><el-switch v-model="form[f.key]" :disabled="!changed[f.key]"/></el-form-item>
  <el-form-item v-for="f in [{key:'intervalMs',label:'扫描间隔 ms'},{key:'windowMs',label:'扫描窗口 ms'}]" :key="f.key" :label="f.label"><el-checkbox v-model="changed[f.key]">本次修改</el-checkbox><el-input-number v-model="form[f.key]" :min="10" :max="10240" :disabled="!changed[f.key]"/></el-form-item>
  <el-form-item label="最低 RSSI"><el-checkbox v-model="changed.minRssi">本次修改</el-checkbox><el-checkbox v-if="section!=='legacy-scan'" v-model="form.clearRssi" :disabled="!changed.minRssi">移除阈值</el-checkbox><el-input-number v-model="form.minRssi" :min="-127" :max="20" :disabled="!changed.minRssi||form.clearRssi"/></el-form-item>
  <el-form-item v-for="f in [{key:'serviceUuids',label:'服务 UUID（逗号分隔，最多 128）'},{key:'manufacturerIds',label:'厂商 ID（十进制，逗号分隔，最多 128）'}]" :key="f.key" :label="f.label"><el-checkbox v-model="changed[f.key]">整体替换列表（留空表示清空）</el-checkbox><el-input v-model="form[f.key]" type="textarea" :disabled="!changed[f.key]"/></el-form-item>
  <el-checkbox v-if="section!=='legacy-scan'" v-model="changed.beaconRules">整体替换 Beacon 规则（最多 8 条，按顺序首条匹配）</el-checkbox>
  <div v-if="changed.beaconRules"><fieldset v-for="(b,index) in form.beaconRules" :key="index"><legend>规则 {{Number(index)+1}}</legend><el-select v-model="b.action" aria-label="Beacon 动作"><el-option label="允许" value="ALLOW"/><el-option label="拒绝" value="DENY"/></el-select><el-select v-model="b.reportKinds" multiple aria-label="Beacon 报文类型"><el-option v-for="k in ['LEGACY_ADV','LEGACY_SCAN_RSP','EXT_ADV','EXT_SCAN_RSP']" :key="k" :label="k" :value="k"/></el-select><label>AD Type <el-input-number v-model="b.adType" :min="1" :max="255"/></label><label>偏移 <el-input-number v-model="b.offset" :min="0" :max="253"/></label><el-select v-model="b.encoding" aria-label="Beacon 编码"><el-option label="Hex" value="HEX"/><el-option label="Base64" value="BASE64"/></el-select><el-input v-model="b.value" placeholder="匹配值（1–24 字节）" aria-label="Beacon 匹配值"/><el-input v-model="b.mask" placeholder="掩码（与值等长）" aria-label="Beacon 掩码"/><el-button type="danger" plain @click="form.beaconRules.splice(Number(index),1)">移除规则</el-button></fieldset><el-button :disabled="form.beaconRules.length>=8" @click="addBeacon">添加 Beacon 规则</el-button></div>
 </template>
 <template v-else-if="isAdv">
  <el-form-item label="启用广播"><el-checkbox v-model="changed.enabled">本次修改</el-checkbox><el-switch v-model="form.enabled" :disabled="!changed.enabled"/></el-form-item>
  <el-form-item label="广播模式"><el-checkbox v-model="changed.mode">本次修改</el-checkbox><el-select v-model="form.mode" :disabled="!changed.mode"><el-option label="不可连接 / 不可扫描" value="NONCONNECTABLE"/><el-option label="不可连接 / 可扫描" value="SCANNABLE_NONCONNECTABLE"/></el-select></el-form-item>
  <el-form-item label="广播间隔 ms"><el-checkbox v-model="changed.advInterval">本次修改</el-checkbox><el-input-number v-model="form.advInterval" :min="100" :max="10240" :disabled="!changed.advInterval"/></el-form-item>
  <el-form-item label="载荷输入编码"><el-select v-model="form.encoding"><el-option label="Hex" value="HEX"/><el-option label="Base64" value="BASE64"/></el-select></el-form-item>
  <el-form-item v-for="f in [{key:'advData',label:'完整广播 AD（最多 31 字节）'},{key:'scanResponse',label:'完整扫描响应 AD（最多 31 字节）'}]" :key="f.key" :label="f.label"><el-checkbox v-model="changed[f.key]">整体替换（留空表示清空）</el-checkbox><el-input v-model="form[f.key]" type="textarea" :disabled="!changed[f.key]"/></el-form-item>
 </template>
 <template v-else><el-form-item label="每批记录上限"><el-checkbox v-model="changed.batchMaxRecords">本次修改</el-checkbox><el-input-number v-model="form.batchMaxRecords" :min="1" :max="1000" :disabled="!changed.batchMaxRecords"/></el-form-item><el-form-item label="刷新间隔 ms"><el-checkbox v-model="changed.flushIntervalMs">本次修改</el-checkbox><el-input-number v-model="form.flushIntervalMs" :min="100" :max="60000" :disabled="!changed.flushIntervalMs"/></el-form-item></template>
 </el-form><aside><h3>本次变更</h3><el-alert v-if="preview.error" :title="preview.error" type="info" :closable="false"/><pre v-else>{{pretty(preview.value)}}</pre><el-button type="primary" :disabled="!allowed||!!preview.error||!!task" :loading="busy" @click="submit">提交配置任务</el-button><el-button @click="loadKnown">清除草稿</el-button><el-button v-if="task" @click="router.push('/tasks/'+task.taskId)">查看执行结果</el-button><el-collapse><el-collapse-item title="服务器已知配置（可能不完整）"><pre>{{pretty(snapshot)}}</pre></el-collapse-item><el-collapse-item title="最近已验证变更"><pre>{{pretty(config.reported)}}</pre></el-collapse-item></el-collapse></aside></div>
 </div></template>
<style scoped>.config-grid{display:grid;grid-template-columns:180px minmax(280px,1fr) minmax(230px,.8fr);gap:20px;margin-top:20px}.config-form{min-width:0}.el-form-item :deep(.el-form-item__content){gap:10px}.el-select{min-width:160px;width:100%}fieldset{border:1px solid #dce3eb;border-radius:8px;margin:14px 0;padding:14px;display:grid;gap:10px}legend{font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f7fa;padding:12px;border-radius:8px;font-size:12px;max-height:400px;overflow:auto}aside>.el-button{margin:8px 5px 8px 0}.toolbar{display:flex;gap:16px;align-items:center;margin-bottom:14px}.el-alert{margin-bottom:12px}@media(max-width:1100px){.config-grid{grid-template-columns:1fr}.el-menu{display:flex;flex-wrap:wrap}.el-menu-item{height:40px}}</style>
